<?php
require_once __DIR__.'/includes/functions.php';
$city=get('city');$month=get('month',date('Y-m'));if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=date('Y-m');
$start=$month.'-01';$next=(new DateTime($start))->modify('+1 month')->format('Y-m-d');$params=[$start,$next];
$where='e.event_date>=? AND e.event_date<?';if($city!==''){$where.=' AND e.city=?';$params[]=$city;}
$rows=db_all('SELECT e.*,c.name category FROM events e LEFT JOIN categories c ON c.category_id=e.category_id WHERE '.$where.' ORDER BY e.event_date,e.start_time',$params);
$cities=db_all("SELECT DISTINCT city FROM events WHERE city IS NOT NULL AND city<>'' ORDER BY city");
$byDay=[];foreach($rows as $event)$byDay[(int)substr($event['event_date'],8,2)][]=$event;
$page_title='Fan events';require __DIR__.'/includes/header.php';
?>
<main id="main" class="page"><div class="breadcrumbs"><a href="<?=e(base_url())?>">Home</a><span>Events</span></div><p class="eyebrow">MEET YOUR COMMUNITY</p><h1>Fandom events</h1><p>Discover conventions, screenings and meetups. Times are local to the event venue.</p>
<form method="get" class="filters"><label>City<select name="city"><option value="">All cities</option><?php foreach($cities as $c):?><option <?=$city===$c['city']?'selected':''?>><?=e($c['city'])?></option><?php endforeach;?></select></label><label>Month<input type="month" name="month" value="<?=e($month)?>"></label><div class="filter-actions"><button class="button">Show events</button></div><div class="filter-actions"><button class="secondary" type="button" id="find-nearby">Find nearby</button></div></form><p id="location-status" role="status">Location is optional. Coordinates are used only in your browser.</p>
<details><summary>View month calendar</summary><div class="calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day):?><div class="weekday"><?=$day?></div><?php endforeach; $first=new DateTime($start); for($n=1;$n<(int)$first->format('N');$n++):?><div class="outside"></div><?php endfor;for($d=1;$d<=(int)$first->format('t');$d++):?><div><strong><?=$d?></strong><?php foreach($byDay[$d]??[] as $event):?><a href="#event-<?=$event['event_id']?>"><?=e($event['title'])?></a><?php endforeach;?></div><?php endfor;?></div></details>
<div class="grid three" style="margin-top:25px" id="events-grid"><?php foreach($rows as $event):$coords=$event['latitude']!==null && $event['longitude']!==null;?><article class="panel" id="event-<?=$event['event_id']?>" <?=$coords?'data-event-lat="'.e($event['latitude']).'" data-event-lon="'.e($event['longitude']).'"':''?>><span class="pill"><?=e($event['category']??'Community')?></span><h2 style="margin-top:15px"><?=e($event['title'])?></h2><p><strong><?=e($event['event_date'])?></strong> <?=e(substr($event['start_time']??'',0,5))?><br><?=e($event['venue'])?>, <?=e($event['city'])?> <?=e($event['country'])?></p><p class="distance"></p><p><?=nl2br(e($event['description']))?></p><?php if($event['image_url']):?><img src="<?=e(image_url($event['image_url']))?>" alt="<?=e($event['title'])?>" loading="lazy"><?php endif;?>
<?php if($coords):$lat=(float)$event['latitude'];$lon=(float)$event['longitude'];$bbox=implode(',',[$lon-.018,$lat-.012,$lon+.018,$lat+.012]);?><details><summary>View location map</summary><iframe class="event-map" loading="lazy" title="Map for <?=e($event['title'])?>" src="https://www.openstreetmap.org/export/embed.html?bbox=<?=e(rawurlencode($bbox))?>&amp;layer=mapnik&amp;marker=<?=e(rawurlencode($lat.','.$lon))?>"></iframe><a href="https://www.openstreetmap.org/?mlat=<?=e($lat)?>&amp;mlon=<?=e($lon)?>#map=14/<?=e($lat)?>/<?=e($lon)?>" target="_blank" rel="noopener">Open map</a></details><?php endif;?><div class="actions" style="margin-top:20px"><?php if(safe_url($event['ticket_url'])):?><a class="button small" href="<?=e(safe_url($event['ticket_url']))?>" target="_blank" rel="noopener">Event / ticket link</a><?php endif;?><a href="<?=e(base_url('api/event-calendar.php?id='.$event['event_id']))?>">Add to calendar</a></div></article><?php endforeach;if(!$rows):?><div class="empty"><h2>No events this month</h2><p>Choose another month or city.</p></div><?php endif;?></div></main><?php require __DIR__.'/includes/footer.php';?>
